#[test]
fn scoped_encoder_retains_actual_overage_without_minting_a_new_grant(){let source=crate::OriginalSourceTurnIssuer::new();let turn=source.issue().unwrap();
 use crate::native_encoding::NativeEncodeRetirementRecipient;let mut issuer=NativeEncodeAllocationIssuer::new();let mut recipient=NativeEncodeRetirementRecipient::new();let mut output=None;let mut actual=None;let mut pending=None;let mut allocation=None;
 let receipt={let mut observer=|_|true;let mut port=|_:NativeAllocationEvent|Ok(());let mut loan=issuer.scoped_loan(&mut port);let mut work=|_,_|Ok(());let mut native=NativeEncodeControl::new_scoped_source(8,16,&mut observer,&mut loan,&mut work);native.install_retirement_recipient(&mut recipient).unwrap();let mut payer=AcceptWork{posted:0};let mut work_issuer=NativeEncodeWorkIssuer::new();let mut work_loan=work_issuer.loan(&mut payer);native.with_work_recipient(&mut work_loan,|native|{assert!(native.prepare_work(1)?);allocation=Some(native.allocate_effect(8,&mut actual,&mut pending,&mut |actual|{let mut bytes=Vec::<u8>::new();bytes.try_reserve_exact(16).map_err(|_|error("allocator refused"))?;*actual=Some(bytes.capacity());output=Some(bytes);Ok(())}));native.commit_work(1)?;Ok::<(),ValueError>(())}).unwrap();drop(work_loan);assert_eq!(payer.posted,1);assert_eq!(native.owned_bytes(),16);match native.pause_scoped_source(turn.witness(),&pending){Ok(receipt)=>receipt,Err(_)=>panic!("actual overage must remain detachable")}};
 let allocation=allocation.take().unwrap();assert!(allocation.extent_refusal.is_some());assert_eq!(receipt.owned_bytes(),16);close(allocation);
 let receipt={let mut observer=|_|true;let mut port=|_:NativeAllocationEvent|Ok(());let mut loan=issuer.scoped_loan(&mut port);let mut work=|_,_|Ok(());let mut native=match NativeEncodeControl::resume_scoped_source(receipt,turn.witness(),0,16,&mut observer,&mut loan,&mut work,&mut recipient){Ok(native)=>native,Err(_)=>panic!("overage receipt must rebind")};assert_eq!(native.owned_bytes(),16);assert_eq!(native.maximum_bytes(),16);let mut actual=None;let mut pending=None;let denied=native.allocate_effect(1,&mut actual,&mut pending,&mut |_|panic!("unfunded allocation cannot run"));assert!(denied.primary.is_some());close(denied);match native.pause_scoped_source(turn.witness(),&pending){Ok(receipt)=>receipt,Err(_)=>panic!("denied extra allocation must preserve receipt")}};
 let receipt={let mut observer=|_|true;let mut port=|_:NativeAllocationEvent|Ok(());let mut loan=issuer.scoped_loan(&mut port);let mut work=|_,_|Ok(());let native=match NativeEncodeControl::resume_scoped_source(receipt,turn.witness(),3,16,&mut observer,&mut loan,&mut work,&mut recipient){Ok(native)=>native,Err(_)=>panic!("real additional grant must rebind")};assert_eq!(native.owned_bytes(),16);assert_eq!(native.maximum_bytes(),19);match native.pause_scoped_source(turn.witness(),&None){Ok(receipt)=>receipt,Err(_)=>panic!("Source receipt must detach")}};close(receipt);close(output.take().unwrap());
}

#[test]
fn scoped_source_retains_born_backing_and_original_pending_allocation(){
 struct Allocation{posted:Option<usize>,source:crate::OriginalSourceTurnIdentity}
 impl crate::NativeAllocationAuthorityPort for Allocation{type Context<'turn,'source>=&'turn crate::OriginalSourceTurn where 'source:'turn;fn validate_context<'turn,'source>(&self,turn:&Self::Context<'turn,'source>)->Result<(),ValueError> where 'source:'turn{if turn.identity()==self.source{Ok(())}else{Err(error("foreign parent Source turn"))}}fn source_turn<'turn,'source>(&self,turn:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{Some(turn.identity())}fn receive<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,event:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{if let NativeAllocationEvent::Post{actual,..}=event{assert!(self.posted.replace(actual).is_none())}Ok(reply.complete(Ok(())))}fn recover<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,_:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{Ok(reply.pending())}}
 struct WorkSource{source:crate::OriginalSourceTurnIdentity}impl crate::OriginalWorkRecipient for WorkSource{type Context<'turn,'source>=&'turn crate::OriginalSourceTurn where 'source:'turn;fn validate_context<'turn,'source>(&self,turn:&Self::Context<'turn,'source>)->Result<(),ValueError> where 'source:'turn{if turn.identity()==self.source{Ok(())}else{Err(error("foreign parent Source turn"))}}fn source_turn<'turn,'source>(&self,turn:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{Some(turn.identity())}fn admits<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,quote:crate::OriginalWorkQuote<'reply>,_:u64,_:u64)->crate::OriginalWorkQuoteComplete<'reply> where 'source:'turn{quote.complete(Ok(true))}}
 struct Physical{submitted:RetainedCloneProgress,source:crate::OriginalSourceTurnIdentity}impl crate::OriginalConstructionRecipient for Physical{type Context<'turn,'source>=&'turn crate::OriginalSourceTurn where 'source:'turn;fn validate_context<'turn,'source>(&self,turn:&Self::Context<'turn,'source>)->Result<(),ValueError> where 'source:'turn{if turn.identity()==self.source{Ok(())}else{Err(error("foreign parent Source turn"))}}fn submitted<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->RetainedCloneProgress where 'source:'turn{self.submitted}fn source_turn<'turn,'source>(&self,turn:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{Some(turn.identity())}fn grant<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,quote:crate::OriginalConstructionGrant<'reply>)->crate::OriginalConstructionGrantComplete<'reply> where 'source:'turn{quote.complete(Ok(grant()))}fn accept<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,receipt:crate::OriginalConstructionAccept<'reply>)->crate::OriginalConstructionAcceptComplete<'reply> where 'source:'turn{let result=self.submitted.checked_add(receipt.progress());match result{Ok(progress)=>{self.submitted=progress;receipt.complete(Ok(()))},Err(error)=>receipt.complete(Err(error))}}}
 let source=crate::OriginalSourceTurnIssuer::new();let turn=source.issue().unwrap();let foreign=source.issue().unwrap();let mut allocation=crate::NativeAllocationAuthority::new(Allocation{posted:None,source:turn.identity()});let mut work=crate::OriginalWorkAuthority::new(WorkSource{source:turn.identity()});let mut physical=crate::OriginalConstructionAuthority::new(Physical{submitted:Default::default(),source:turn.identity()});let mut recipient=crate::native_encoding::NativeEncodeRetirementRecipient::new();let mut output=None;
 let(mut allocation_turn,mut work_turn,mut physical_turn)=(&turn,&turn,&turn);allocation.with_send_loan(&mut allocation_turn,|port|work.with_loan(&mut work_turn,|work_loan|physical.with_loan(&mut physical_turn,|physical_loan|{let mut observer=|_|true;let mut span=|_,_|Ok(());let mut control=NativeEncodeControl::new_scoped_source(64,16,&mut observer,port,&mut span);control.install_retirement_recipient(&mut recipient).unwrap();let mut state=Some(NativeEncodeEffectState::default());let mut failure=None;let mut local=RetainedCloneProgress::default();let header=std::mem::size_of::<Vec<u8>>();let demand=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:header,maximum_capacity_bytes:64,maximum_depth:1,..Default::default()};let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||control.with_work_recipient(work_loan,|control|control.with_construction_recipient(physical_loan,|control|{let _=control.effect_allocated(grant(),&mut local,demand,Some(64),&mut state.as_mut().unwrap().view(),&mut failure,&mut |performed,progress,actual,attempted_work|{*attempted_work=Some(1);let layout=std::alloc::Layout::array::<u8>(8).unwrap();let pointer=unsafe{std::alloc::alloc(layout)};if pointer.is_null(){*actual=Some(0);return Err(error("actual allocation refused"))}let bytes=unsafe{Vec::from_raw_parts(pointer,0,8)};*actual=Some(bytes.capacity());*performed=true;*progress=RetainedCloneProgress{copied_items:1,copied_bytes:header,retained_capacity_bytes:bytes.capacity(),..Default::default()};output=Some(bytes);panic!("original allocation interrupted")});Ok::<(),ValueError>(())}))));assert!(interrupted.is_err());let actual=state.as_ref().unwrap().actual.unwrap();let pointer=output.as_ref().unwrap().as_ptr();let control=match control.pause_scoped_source(foreign.witness(),work_loan,physical_loan,&mut state,&mut failure){Err((error,control))=>{close(error);control},Ok(_)=>panic!("foreign Source token bound to original parent authorities")};let receipt=control.pause_scoped_source(turn.witness(),work_loan,physical_loan,&mut state,&mut failure).ok().unwrap();assert!(state.is_none()&&failure.is_none());let mut observer=|_|true;let mut span=|_,_|Ok(());let receipt=match NativeEncodeControl::resume_scoped_source(receipt,foreign.witness(),&mut observer,port,&mut span,&mut recipient,work_loan,physical_loan,&mut state,&mut failure){Err((receipt,error))=>{close(error);receipt},Ok(_)=>panic!("foreign Source dispatch resumed pending allocation")};assert!(state.is_none()&&failure.is_none());let mut observer=|_|true;let mut span=|_,_|Ok(());let mut control=NativeEncodeControl::resume_scoped_source(receipt,turn.witness(),&mut observer,port,&mut span,&mut recipient,work_loan,physical_loan,&mut state,&mut failure).ok().unwrap();let resumed=control.with_work_recipient(work_loan,|control|control.with_construction_recipient(physical_loan,|control|{let resumed=control.effect_allocated(grant(),&mut local,demand,Some(64),&mut state.as_mut().unwrap().view(),&mut failure,&mut |_,_,_,_|panic!("original allocator must not replay"));Ok::<_,ValueError>(resumed)})).unwrap();assert_eq!(resumed.work,1);assert!(matches!(resumed.result,Ok(Some(()))));assert_eq!(state.as_ref().unwrap().actual,Some(actual));assert_eq!(output.as_ref().unwrap().as_ptr(),pointer);assert_eq!(control.owned_bytes(),64);drop(control);close(state.take().unwrap());})).unwrap().unwrap()).unwrap();assert_eq!(allocation.inspect_port(|port|port.posted),output.as_ref().map(Vec::capacity));assert_eq!(physical.inspect(|port|port.submitted.retained_capacity_bytes),output.as_ref().unwrap().capacity());close(output.take().unwrap());
}
